// Background sync for contact forms (when back online)
self.addEventListener('sync', (event) => {
  if (event.tag === 'contact-form-sync') {
    event.waitUntil(syncContactForms())
  }
})

async function syncContactForms() {
  try {
    const storedForms = await getStoredContactForms()
    
    for (const form of storedForms) {
      try {
        await fetch('/api/contacts', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(form.data)
        })
        
        // Remove successfully synced form
        await removeStoredContactForm(form.id)
        console.log('Contact form synced successfully')
      } catch (error) {
        console.log('Failed to sync contact form:', error)
      }
    }
  } catch (error) {
    console.log('Background sync failed:', error)
  }
}

async function getStoredContactForms() {
  // Implementation would depend on IndexedDB usage
  return []
}

async function removeStoredContactForm(id) {
  // Implementation would depend on IndexedDB usage
  console.log('Removing contact form:', id)
}

// Push Notifications Support
self.addEventListener("push", event => {
  const data = event.data?.json() || {};
  
  const options = {
    body: data.body || "Ново известие от Pravda ST.",
    icon: "/favicon-192.png",
    badge: "/favicon-192.png", 
    image: data.image || "/og-images/default.svg",
    data: {
      url: data.url || "/",
      timestamp: Date.now(),
      ...data
    },
    actions: [
      {
        action: 'view',
        title: 'Виж повече',
        icon: '/favicon-192.png'
      },
      {
        action: 'close',
        title: 'Затвори',
        icon: '/favicon-192.png'
      }
    ],
    requireInteraction: false,
    tag: data.tag || 'pravda-notification',
    renotify: true,
    vibrate: [200, 100, 200],
    silent: false
  };

  event.waitUntil(
    self.registration.showNotification(
      data.title || "Pravda ST", 
      options
    )
  );
});

// Handle notification clicks
self.addEventListener("notificationclick", event => {
  event.notification.close();
  
  if (event.action === 'close') {
    return;
  }
  
  const urlToOpen = event.notification.data.url || '/';
  
  event.waitUntil(
    clients.matchAll({
      type: 'window',
      includeUncontrolled: true
    }).then(clientList => {
      // Check if there's already a window open
      for (const client of clientList) {
        if (client.url.includes(new URL(urlToOpen).pathname) && 'focus' in client) {
          return client.focus();
        }
      }
      
      // Open new window if none exists
      if (clients.openWindow) {
        return clients.openWindow(urlToOpen);
      }
    })
  );
});